import assert from 'node:assert/strict';
import { test } from 'node:test';
import { taskLabel } from '../src/labels.ts';

test('completed task has [x] prefix', () => {
  assert.equal(taskLabel('ship release', true), '[x] ship release');
});

test('incomplete task keeps [ ] prefix', () => {
  assert.equal(taskLabel('ship release', false), '[ ] ship release');
});

test('preserves empty name', () => {
  assert.equal(taskLabel('', true), '[x] ');
  assert.equal(taskLabel('', false), '[ ] ');
});

test('preserves whitespace and special characters in name', () => {
  assert.equal(taskLabel('  spaced  ', true), '[x]   spaced  ');
  assert.equal(taskLabel('fix: #123 [urgent]!', true), '[x] fix: #123 [urgent]!');
  assert.equal(taskLabel('fix: #123 [urgent]!', false), '[ ] fix: #123 [urgent]!');
});
